import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;

public class CacheLeakRemediation {
    // Solution: Immutable key record guarantees stable hash codes
    public record TenantKey(String tenantId, String environment) {}

    public static void cleanExpiredTenants(Map<TenantKey, Long> expiryMap, long now) {
        // Solution: Safe iterator removal prevents ConcurrentModificationException
        Iterator<Map.Entry<TenantKey, Long>> it = expiryMap.entrySet().iterator();
        while (it.hasNext()) {
            Map.Entry<TenantKey, Long> entry = it.next();
            if (entry.getValue() < now) {
                it.remove(); // Safely removes from backing map
            }
        }
    }

    public static void main(String[] args) {
        Map<TenantKey, Long> expiries = new HashMap<>();
        TenantKey k1 = new TenantKey("T1", "PROD");
        TenantKey k2 = new TenantKey("T2", "DEV");

        expiries.put(k1, 1000L);
        expiries.put(k2, 2000L);

        cleanExpiredTenants(expiries, 1500L);
        System.out.println("Remaining active tenants: " + expiries.keySet());
    }
}

