practiceProblems.solutionCode:
import java.util.Map;

public class GradeRemover {
    public static void removeFailingGrades(Map<String, Integer> gradeMap, int threshold) {
        if (gradeMap != null) {
            gradeMap.entrySet().removeIf(entry -> entry.getValue() == null || entry.getValue() < threshold);
        }
    }
}

