import java.util.Map;

public class LeakDetector {
    public static class MutableKey {
        public String name;
        public MutableKey(String name) { this.name = name; }
        public int hashCode() { return name.hashCode(); }
        public boolean equals(Object o) {
            return o instanceof MutableKey k && name.equals(k.name);
        }
    }

    public static String findLeakedValue(Map<MutableKey, String> map, String targetName) {
        if (map == null || targetName == null) return null;
        for (Map.Entry<MutableKey, String> entry : map.entrySet()) {
            if (entry.getKey() != null && targetName.equals(entry.getKey().name)) {
                return entry.getValue();
            }
        }
        return null;
    }
}
